package ergodexcl

/**
 * ErgoDEX concentrated-liquidity positions on mainnet, pinned: the position script every position box sits at, the
 * swap script it runs from context variable 1 (named in the position script by its Blake2b256), and the token of the
 * config box. A position swaps only while the config box lists the swap script's hash in R8; the config box also holds
 * the protocol fee's key in R4 and its parameters in R5.
 */
object ErgoDexClContracts {

  /** The position script, as every position box on chain carries it. */
  final val PositionErgoTree: String =
    ""

  /** The swap script's bytes, as a leg passes them in context variable 1. */
  final val SwapScript: String =
    ""

  /** Blake2b256 of [[SwapScript]], the hash the position script and the config box's R8 name. */
  final val SwapScriptHash: String = "70286f997a21187839b4902d464335eafb14c4c397f846ab0c12193b142fe67d"

  /** The token the one config box holds first. */
  final val ConfigToken: String = "289c9c0e8a394769cf5b9622546e58b263d20dd2504eabdcaa01515bf149da8b"
}
